import {iconSvg} from './icons.mjs';
export const SECTION_KEYS=['opening','invitation','story','day','place','program','details','rsvp'];
export const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
export function safeUrl(value,{external=false}={}){if(typeof value!=='string'||!value.trim())return '';const v=value.trim();if(!external&&(/^data:(image|audio)\/[a-z0-9.+-]+;base64,[a-z0-9+/=]+$/i.test(v)||/^blob:https?:\/\/[^\s"'<>]+$/i.test(v)))return v;if(/[\u0000-\u0020\\]/.test(v)||v.startsWith('//'))return '';try{const u=new URL(v,'https://template.invalid/');if(!['https:','http:'].includes(u.protocol))return '';if(external&&!/^https?:\/\//.test(v))return '';return v}catch{return ''}}
export function mergeConfig(base,patch){if(!patch||typeof patch!=='object'||Array.isArray(patch))return structuredClone(patch);const out=structuredClone(base||{});for(const [k,v] of Object.entries(patch)){if(['__proto__','constructor','prototype'].includes(k))throw new Error('Unsafe config key');out[k]=v&&typeof v==='object'&&!Array.isArray(v)?mergeConfig(out[k],v):structuredClone(v)}return out}
export function validateConfig(c){const errors=[];const need=(ok,path)=>{if(!ok)errors.push(path)};
 need(c?.schemaVersion===1,'schemaVersion must be 1');need(typeof c?.id==='string'&&/^[a-zA-Z0-9_-]+$/.test(c.id),'id');
 for(const key of ['meta','couple','event','theme','assets','layout','header','opening','invitation','story','day','place','program','details','rsvp','footer','ui'])need(c?.[key]&&typeof c[key]==='object',key);
 if(errors.length)return errors;
 for(const k of ['firstName','secondName'])need(typeof c.couple[k]==='string'&&!!c.couple[k].trim(),`couple.${k}`);
 need(/^\d{4}-\d{2}-\d{2}$/.test(c.event.date)&&!isNaN(Date.parse(c.event.date))&&new Date(c.event.date).toISOString().slice(0,10)===c.event.date,'event.date');
 for(const k of ['startAt','endAt'])need(typeof c.event[k]==='string'&&/T\d{2}:\d{2}:\d{2}(Z|[+-]\d{2}:\d{2})$/.test(c.event[k])&&!isNaN(Date.parse(c.event[k])),`event.${k} (ISO timestamp with offset)`);
 need(Date.parse(c.event.endAt)>Date.parse(c.event.startAt),'event.endAt must follow startAt');
 try{new Intl.DateTimeFormat(c.locale,{timeZone:c.event.timeZone}).format()}catch{errors.push('locale or event.timeZone')}
 try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:c.event.timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(c.event.startAt));const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));need(`${v.year}-${v.month}-${v.day}`===c.event.date,'event.date must match startAt in event.timeZone')}catch{}
 need(Array.isArray(c.layout.sections)&&new Set(c.layout.sections).size===c.layout.sections.length&&c.layout.sections.every(s=>SECTION_KEYS.includes(s)),'layout.sections');
 if(c.layout.sections?.includes('opening')&&c.opening.enabled)need(c.layout.sections[0]==='opening','opening must be first');
 for(const [k,v] of Object.entries(c.theme))need(/^#[0-9a-f]{6}$/i.test(v),`theme.${k}`);
 for(const [k,v] of Object.entries(c.assets))need(!!safeUrl(v),`assets.${k}`);
 for(const k of ['story','place']){const p=c[k].photo;need(p&&typeof p.src==='string',`${k}.photo`);if(p){need(!p.src||!!safeUrl(p.src),`${k}.photo.src`);need(p.position&&['x','y'].every(a=>Number.isFinite(p.position[a])&&p.position[a]>=0&&p.position[a]<=100),`${k}.photo.position`);need(/^\d+(?:\.\d+)?\s*\/\s*\d+(?:\.\d+)?$/.test(p.aspectRatio)&&p.aspectRatio.split('/').every(n=>Number(n)>0),`${k}.photo.aspectRatio`);}}
 need(!c.place.mapUrl||!!safeUrl(c.place.mapUrl,{external:true}),'place.mapUrl');
 need(Array.isArray(c.program.items),'program.items');const eventIds=new Set();for(const [i,item] of (c.program.items||[]).entries()){need(typeof item.id==='string'&&!eventIds.has(item.id),`program.items[${i}].id`);eventIds.add(item.id);need(/^([01]\d|2[0-3]):[0-5]\d$/.test(item.time),`program.items[${i}].time`);need(typeof item.title==='string'&&typeof item.description==='string',`program.items[${i}] text`);need(typeof item.icon==='string'||(item.icon&&!!safeUrl(item.icon.src)),`program.items[${i}].icon`)}
 need(Array.isArray(c.day.weekdays)&&c.day.weekdays.length===7,'day.weekdays');need(Array.isArray(c.day.countdownUnits)&&c.day.countdownUnits.length===3,'day.countdownUnits');
 for(const color of c.details.colors||[])need(/^#[0-9a-f]{6}$/i.test(color.color),'details.colors');
 const ids=new Set();need(Array.isArray(c.rsvp.fields),'rsvp.fields');for(const field of c.rsvp.fields||[]){need(/^[a-z][a-z0-9_-]*$/i.test(field.id)&&!ids.has(field.id),`rsvp.fields id ${field.id}`);ids.add(field.id);need(['text','email','tel','number','textarea','radio','select'].includes(field.type),`rsvp.fields type ${field.type}`);if(['radio','select'].includes(field.type))need(Array.isArray(field.options)&&field.options.length>0&&new Set(field.options.map(o=>o.value)).size===field.options.length,`rsvp.fields ${field.id} options`);if(field.maxLength!==undefined)need(Number.isInteger(field.maxLength)&&field.maxLength>0,`rsvp.fields ${field.id} maxLength`)}
 if(c.music){need(typeof c.music.enabled==='boolean','music.enabled');need(typeof c.music.src==='string'&&(!c.music.src||!!safeUrl(c.music.src)),'music.src');need(Number.isFinite(c.music.volume)&&c.music.volume>=0&&c.music.volume<=1,'music.volume');need(typeof c.music.loop==='boolean','music.loop');for(const key of ['play','pause','loading','error'])need(typeof c.music.labels?.[key]==='string'&&!!c.music.labels[key].trim(),`music.labels.${key}`);}
 need(['local','endpoint'].includes(c.rsvp.submission?.mode),'rsvp.submission.mode');if(c.rsvp.submission?.mode==='endpoint')need(!!safeUrl(c.rsvp.submission.endpoint),'rsvp.submission.endpoint');return errors;
}
const title=t=>`${e(t.text)}${t.accent?`<br><em>${e(t.accent)}</em>`:''}`;
const pList=arr=>(arr||[]).map(t=>`<p>${e(t)}</p>`).join('');
const arrow=(label,key='arrowRight')=>`${e(label)}${iconSvg(key)}`;
const mark=s=>s.marker?`<div class="section-mark reveal">${e(s.marker)}</div>`:'';
const eyebrow=s=>s.eyebrow?`<p class="eyebrow reveal">${e(s.eyebrow)}</p>`:'';
const divider=c=>`<img class="divider reveal" src="${e(safeUrl(c.assets.divider))}" alt="" loading="lazy">`;
const names=c=>`<span>${e(c.couple.firstName)}</span><i>${e(c.couple.separator)}</i><span>${e(c.couple.secondName)}</span>`;
export function photoMarkup(p,frame,c){const source=safeUrl(p.src);return `<div class="photo-shell ${frame?'story-art':'place-photo'} reveal" style="aspect-ratio:${e(p.aspectRatio)}"><div class="photo-aperture ${frame?'oval':'arched'}">${source?`<img class="couple-photo" src="${e(source)}" alt="${e(p.alt)}" loading="lazy" decoding="async" style="object-position:${p.position.x}% ${p.position.y}%">`:''}<div class="photo-placeholder" ${source?'hidden':''}>${iconSvg('camera')}<span>${e(p.placeholder)}</span></div></div>${frame?`<img class="photo-frame" src="${e(safeUrl(c.assets.frame))}" alt="" loading="lazy">`:''}</div>`}
export function fieldMarkup(f){const id=`guest-${f.id}`,req=f.required?' required':'',max=f.maxLength?` maxlength="${f.maxLength}"`:'',attrs=`id="${id}" name="${e(f.id)}"${req}`,ph=`placeholder="${e(f.placeholder)}"`;
 if(f.type==='radio')return `<fieldset><legend>${e(f.label)}</legend>${f.options.map(o=>`<label class="radio"><input type="radio" name="${e(f.id)}" value="${e(o.value)}"${req}><span>${e(o.label)}</span></label>`).join('')}</fieldset>`;
 let input=f.type==='textarea'?`<textarea ${attrs} ${ph}${max} rows="3"></textarea>`:f.type==='select'?`<select ${attrs}><option value="">${e(f.placeholder)}</option>${f.options.map(o=>`<option value="${e(o.value)}">${e(o.label)}</option>`).join('')}</select>`:`<input ${attrs} type="${e(f.type)}" ${ph}${max}${f.autocomplete?` autocomplete="${e(f.autocomplete)}"`:''}${Number.isFinite(f.min)?` min="${f.min}"`:''}${Number.isFinite(f.max)?` max="${f.max}"`:''}>`;
 return `<div class="form-field"><label for="${id}">${e(f.label)}</label>${input}</div>`;
}
export function renderMarkup(c){const errors=validateConfig(c);if(errors.length)throw new Error('Invalid invitation config: '+errors.join(', '));const active=c.layout.sections.filter(k=>c[k].enabled!==false),isActive=k=>active.includes(k);const d=new Date(c.event.date+'T12:00:00Z'),format=opts=>new Intl.DateTimeFormat(c.locale,{...opts,timeZone:'UTC'}).format(d),short=c.event.date.split('-').reverse().join(' · '),year=d.getUTCFullYear();
 const sections={
 opening:()=>`<section class="opening" id="opening" aria-label="${e(c.opening.ariaLabel)}"><div class="opening-sticky"><div class="hero-heading">${eyebrow(c.opening)}<h1>${title(c.opening.title)}</h1><p class="hero-description">${e(c.opening.description)}</p></div><div class="envelope-stage" aria-hidden="true"><div class="envelope"><div class="envelope-back"></div><div class="letter"><div class="letter-copy"><span class="letter-kicker">${e(c.opening.letterLabel)}</span><strong>${e(c.couple.firstName)} <i>${e(c.couple.separator)}</i> ${e(c.couple.secondName)}</strong><span class="letter-date">${e(short)}</span></div></div><div class="envelope-pocket"><img src="${e(safeUrl(c.assets.pocket))}" alt=""></div><div class="envelope-flap"><img src="${e(safeUrl(c.assets.flap))}" alt=""></div><img class="wax-seal" src="${e(safeUrl(c.assets.seal))}" alt=""></div></div><button class="scroll-prompt" id="open-letter"><span class="scroll-line"></span>${arrow(c.opening.scrollLabel,'arrowDown')}</button><div class="hero-side left">${e(c.opening.sideLabel)}</div><div class="hero-side right">${year}</div></div></section>`,
 invitation:()=>`<section class="invitation section" id="invitation">${mark(c.invitation)}${eyebrow(c.invitation)}<h2 class="names reveal">${names(c)}</h2>${divider(c)}<div class="invitation-copy reveal"><h3>${e(c.invitation.greeting)}</h3>${pList(c.invitation.paragraphs)}</div><div class="date-row reveal"><span>${e(format({weekday:'long'}))}</span><strong>${e(format({day:'numeric',month:'long'}))}</strong><span>${year}</span></div>${isActive(c.invitation.linkSection)?`<a class="text-link reveal" href="#${e(c.invitation.linkSection)}">${arrow(c.invitation.linkLabel,'arrowDown')}</a>`:''}</section>`,
 story:()=>`<section class="story section" id="story">${photoMarkup(c.story.photo,true,c)}<div class="story-copy">${eyebrow(c.story)}<h2 class="reveal">${title(c.story.title)}</h2><div class="story-paragraphs reveal">${pList(c.story.paragraphs)}</div><div class="handwritten reveal">${e(c.story.signature)}</div></div></section>`,
 day:()=>{const offset=(new Date(Date.UTC(year,d.getUTCMonth(),1)).getUTCDay()+6)%7,days=new Date(Date.UTC(year,d.getUTCMonth()+1,0)).getUTCDate();return `<section class="day section" id="day"><div class="day-intro">${mark(c.day)}${eyebrow(c.day)}<h2 class="reveal">${title(c.day.title)}</h2></div><div class="calendar reveal"><div class="calendar-head"><span>${e(format({month:'long',year:'numeric'}))}</span></div><div class="calendar-week">${c.day.weekdays.map(t=>`<span>${e(t)}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:offset+days},(_,i)=>`<span ${i-offset+1===d.getUTCDate()?`class="chosen" aria-label="${e(c.day.selectedDateLabel)}"`:''}>${i<offset?'':i-offset+1}</span>`).join('')}</div><button class="text-link" id="calendar-download">${arrow(c.day.calendarLabel)}</button></div><div class="countdown reveal"><span>${e(c.day.countdownLabel)}</span><div id="countdown" aria-live="off"></div></div></section>`},
 place:()=>`<section class="place section" id="place">${photoMarkup(c.place.photo,false,c)}<div class="place-copy">${mark(c.place)}${eyebrow(c.place)}<h2 class="reveal">${e(c.place.title)}</h2><p class="reveal">${e(c.place.address)}</p><p class="place-note reveal">${e(c.place.description)}</p>${c.place.mapUrl?`<a class="pill reveal" target="_blank" rel="noopener noreferrer" href="${e(safeUrl(c.place.mapUrl))}">${arrow(c.place.mapLabel)}</a>`:`<span class="location-pending reveal">${e(c.place.pendingLabel)}</span>`}</div></section>`,
 program:()=>`<section class="program section" id="program">${mark(c.program)}${eyebrow(c.program)}<h2 class="reveal">${title(c.program.title)}</h2><div class="timeline">${c.program.items.map(item=>`<article class="timeline-item reveal" data-event-id="${e(item.id)}"><time datetime="${e(c.event.date+'T'+item.time)}">${e(item.time)}</time><div class="timeline-point" aria-hidden="true">${typeof item.icon==='string'?iconSvg(item.icon):`<img src="${e(safeUrl(item.icon.src))}" alt="">`}</div><div><h3>${e(item.title)}</h3><p>${e(item.description)}</p></div></article>`).join('')}</div><p class="small-note reveal">${e(c.program.note)}</p></section>`,
 details:()=>`<section class="details section" id="details"><div>${eyebrow(c.details)}<h2 class="reveal">${title(c.details.title)}</h2></div><div class="details-copy"><p class="reveal">${e(c.details.description)}</p><div class="swatches reveal">${c.details.colors.map(x=>`<span style="--swatch:${x.color}" aria-label="${e(x.label)}"></span>`).join('')}</div><small class="reveal">${e(c.details.colors.map(x=>x.label).join(' · '))}</small></div></section>`,
 rsvp:()=>`<section class="rsvp section" id="rsvp"><div class="rsvp-heading">${mark(c.rsvp)}<h2 class="reveal">${title(c.rsvp.title)}</h2><p class="reveal">${e(c.rsvp.description)}</p>${divider(c)}</div><div class="rsvp-card reveal"><form id="rsvp-form"><p class="eyebrow">${e(c.rsvp.formTitle)}</p>${c.rsvp.fields.map(fieldMarkup).join('')}<button class="submit" type="submit">${arrow(c.rsvp.submitLabel)}</button><p class="form-note">${e(c.rsvp.privacyNote)}</p><p id="form-status" role="status"></p><button type="button" id="answer-download" class="text-link" hidden>${arrow(c.rsvp.downloadLabel,'arrowDown')}</button></form></div></section>`
 };
 const music=c.music?.enabled&&safeUrl(c.music.src)?`<aside class="music-player"><button id="music-toggle" type="button" aria-label="${e(c.music.labels.play)}" title="${e(c.music.labels.play)}" aria-pressed="false" aria-controls="invitation-audio">${iconSvg('gramophone')}<span class="music-indicator" aria-hidden="true"></span></button><p id="music-status" class="music-status" role="status" hidden></p><audio id="invitation-audio" src="${e(safeUrl(c.music.src))}" preload="none" ${c.music.loop?'loop':''}></audio></aside>`:'';
 const first=active[0]||'';return `<div class="reading-progress" aria-hidden="true"></div><header><a class="brand" href="#${first}" aria-label="${e(c.header.homeLabel)}">${e(c.header.brand)} <i>${e(c.header.brandAccent)}</i></a><nav aria-label="${e(c.header.navigationLabel)}">${c.header.links.filter(l=>isActive(l.section)).map(l=>`<a href="#${e(l.section)}" ${l.section==='rsvp'?'class="nav-rsvp"':''}>${e(l.label)}</a>`).join('')}</nav></header><main>${active.map(k=>sections[k]()).join('')}<footer><p class="eyebrow">${e(c.footer.eyebrow)}</p><div class="footer-names">${names(c)}</div><span>${e(short)}</span>${first?`<a href="#${first}">${arrow(c.footer.backLabel,'arrowUp')}</a>`:''}<small>${e(c.footer.note)}</small></footer></main>${music}`;
}
export function calendarText(c){const escape=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Ivory Letter//Invitation//EN','BEGIN:VEVENT',`UID:${c.id}@ivory-letter`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(c.event.startAt)}`,`DTEND:${stamp(c.event.endAt)}`,`SUMMARY:${escape(c.event.calendarTitle)}`,`LOCATION:${escape(c.place.title+', '+c.place.address)}`,`DESCRIPTION:${escape(c.event.calendarDescription)}`,'END:VEVENT','END:VCALENDAR'];return lines.map(line=>{let out='',length=0;for(const char of line){const bytes=new TextEncoder().encode(char).length;if(length+bytes>73){out+='\r\n ';length=1}out+=char;length+=bytes}return out}).join('\r\n')+'\r\n'}
